package org.apache.curator.framework.imps;

import com.google.common.annotations.VisibleForTesting;
import java.util.Optional;
import java.util.UUID;
import org.apache.curator.framework.api.CreateBuilderMain;
import org.apache.curator.utils.ZKPaths;

public final class ProtectedUtils {
  private ProtectedUtils();
  @VisibleForTesting static final String PROTECTED_PREFIX;
  @VisibleForTesting static final char PROTECTED_SEPARATOR;
  @VisibleForTesting static final int PROTECTED_PREFIX_WITH_UUID_LENGTH;
  public static String getProtectedPrefix(final String protectedId) {
    return PROTECTED_PREFIX + protectedId + PROTECTED_SEPARATOR;
  }
  private static String extractProtectedIdInternal(final String znodeName) {
    return znodeName.substring(3, 39);
  }
  public static boolean isProtectedZNode(final String znodeName) {
    return znodeName.length() > 40 && znodeName.startsWith(PROTECTED_PREFIX) && znodeName.charAt(PROTECTED_PREFIX_WITH_UUID_LENGTH - 1) == PROTECTED_SEPARATOR;
  }
  public static String normalize(final String znodeName) {
    return isProtectedZNode(znodeName) ? znodeName.substring(40) : znodeName;
  }
  public static String normalizePath(final String path) {
    final ZKPaths.PathAndNode pathAndNode = ZKPaths.getPathAndNode(path);
    return ZKPaths.makePath(pathAndNode.getPath(), normalize(pathAndNode.getNode()));
  }
  public static Optional<String> extractProtectedId(final String znodeName) {
    return isProtectedZNode(znodeName) ? Optional.ofNullable(extractProtectedIdInternal(znodeName)) : Optional.empty();
  }
  public static String toProtectedZNode(final String znodeName, final String protectedId) {
    return protectedId != null ? getProtectedPrefix(protectedId) + znodeName : znodeName;
  }
  public static String toProtectedZNodePath(final String path, final String protectedId) {
    return protectedId != null ? ZKPaths.makePath(ZKPaths.getPathAndNode(path).getPath(), toProtectedZNode(ZKPaths.getPathAndNode(path).getNode(), protectedId)) : path;
  }
}

