import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

import org.apache.hc.core5.annotation.Internal;

@Internal public final class CloseCodec {
  private CloseCodec();
  public static int readCloseCode(final ByteBuffer payloadRO) {
    return payloadRO.remaining() >= 2 ? payloadRO.get() << 8 & 0xFF00 | payloadRO.get() & 0xFF : 1005;
  }
  public static String readCloseReason(final ByteBuffer payloadRO) {
    return payloadRO.hasRemaining() ? new String(payloadRO.slice().array(), StandardCharsets.UTF_8) : "";
  }
  private static boolean isForbiddenOnWire(final int code) {
    return code == 1005 || code == 1006 || code == 1015;
  }
  private static boolean isRfcDefined(final int code) {
    return code == 1000 || code == 1001 || code == 1002 || code == 1003 || code == 1007 || code == 1008 || code == 1009 || code == 1010 || code == 1011;
  }
  private static boolean isAppRange(final int code) {
    return code >= 3000 && code <= 4999;
  }
  public static boolean isValidToSend(final int code) {
    return code >= 0 && !isForbiddenOnWire(code) && (isRfcDefined(code) || isAppRange(code));
  }
