    reportDesign.setPageHeight(size.height);
    reportDesign.setColumnWidth(size.width);
    reportDesign.setColumnSpacing(0);
    reportDesign.setLeftMargin(0);
    reportDesign.setRightMargin(0);
    reportDesign.setTopMargin(0);
    reportDesign.setBottomMargin(0);
    final JRDesignBand band = new JRDesignBand();
    band.setHeight(size.height);
    this.addGraphics(graphics, band, size, reportDesign);
    reportDesign.setNoData(band);
    reportDesign.setWhenNoDataType(WhenNoDataTypeEnum.NO_DATA_SECTION);
    reportDesign.setProperty(Renderable.PROPERTY_IMAGE_DPI, String.valueOf(Math.round(dpi)));
    return reportDesign;
  }
