    for (final URI graphicFile : graphics) {
      final File file = new File(graphicFile);
      final String imageExpression = '"' + file.getAbsolutePath().replace('\\', '/') + '"';
      band.addElement(this.getImage(imageExpression, size, design));
    }
  }
  private JRDesignElement getImage(final String imageExpression, final Dimension mapSize, final JasperDesign design) {
