public abstract class ScalebarDrawer {
  private final Graphics2D graphics2d;
  private final AffineTransform transform;
  private final ScaleBarRenderSettings settings;
  private final ScalebarAttributeValues params;

  protected ScalebarDrawer(final Graphics2D graphics2d, final ScaleBarRenderSettings settings) {
    this.graphics2d = graphics2d;
    this.transform = graphics2d.getTransform();
    this.settings = settings;
    this.params = settings.getParams();
  }

  public final void draw() {
    final AffineTransform transform = new AffineTransform(this.transform);
    transform.concatenate(getAlignmentTransform());
    this.graphics2d.setTransform(transform);
    if (this.params.getBackgroundColor().getAlpha() > 0) {
      this.graphics2d.setColor(this.params.getBackgroundColor());
      this.graphics2d.fillRect(0, 0, this.settings.getSize().width, this.settings.getSize().height);
    }
    drawLabels(transform, this.params.getOrientation(), this.params.getLabelRotation());
    final AffineTransform lineTransform = new AffineTransform(transform);
    setLineTranslate(lineTransform);
    if (this.params.getOrientation().isHorizontal()) {
      lineTransform.concatenate(AffineTransform.getQuadrantRotateInstance(1));
    }
    this.graphics2d.setTransform(lineTransform);
    this.graphics2d.setStroke(new BasicStroke(this.settings.getLineWidth()));
    this.graphics2d.setColor(this.params.getColor());
    drawBar();
  }

  private AffineTransform getAlignmentTransform() {
    final float offsetX = switch (this.params.getAlign()) {
      case LEFT -> 0;
      case RIGHT -> this.settings.getMaxSize().width - this.settings.getSize().width;
      default -> Math.round(this.settings.getMaxSize().width / 2.0f - this.settings.getSize().width / 2.0f);
    };
    final float offsetY = switch (this.params.getVerticalAlign()) {
      case TOP -> 0;
      case BOTTOM -> this.settings.getMaxSize().height - this.settings.getSize().height;
      default -> Math.round(this.settings.getMaxSize().height / 2.0f - this.settings.getSize().height / 2.0f);
    };
    return AffineTransform.getTranslateInstance(offsetX, offsetY);
  }

  private void setLineTranslate(final AffineTransform lineTransform) {
    lineTransform.translate(
        switch (this.params.getOrientation()) {
          case HORIZONTAL_LABELS_BELOW -> this.settings.getPadding() + this.settings.getLeftLabelMargin();
          case HORIZONTAL_LABELS_ABOVE -> this.settings.getPadding() + this.settings.getBarSize()
              + this.settings.getLabelDistance() + Label.getRotatedHeight(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
          default -> this.settings.getPadding() + this.settings.getBarSize();
        },
        switch (this.params.getOrientation()) {
          case VERTICAL_LABELS_LEFT -> this.settings.getPadding() + Label.getRotatedWidth(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
          default -> this.settings.getPadding() + this.settings.getTopLabelMargin();
        }
    );
  }

  private void setLabelTranslate(final AffineTransform labelTransform) {
    labelTransform.translate(
        switch (this.params.getOrientation()) {
          case HORIZONTAL_LABELS_BELOW -> this.settings.getPadding() + this.settings.getLeftLabelMargin();
          case HORIZONTAL_LABELS_ABOVE -> this.settings.getPadding() + Label.getRotatedWidth(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
          default -> this.settings.getPadding() + this.settings.getBarSize();
        },
        switch (this.params.getOrientation()) {
          case VERTICAL_LABELS_LEFT -> this.settings.getPadding() + Label.getRotatedHeight(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
          default -> this.settings.getPadding() + this.settings.getTopLabelMargin();
        }
    );
  }

  protected abstract void drawBar();

  private void drawLabels(final AffineTransform transform, final Orientation orientation, final float labelRotation) {
    final AffineTransform firstTickTransform = new AffineTransform(transform);
    setLabelTranslate(firstTickTransform);
    for (int i = this.settings.getLabels().size() - 1; i >= 0; i--) {
      final Label label = this.settings.getLabels().get(i);
      final AffineTransform centerTransform = new AffineTransform(firstTickTransform);
      centerTransform.translate(Math.round(label.getGraphicOffset()),
          switch (orientation) {
            case HORIZONTAL_LABELS_BELOW -> -Label.getRotatedHeight(label.getSize(), labelRotation) / 2.0f;
            case HORIZONTAL_LABELS_ABOVE -> Label.getRotatedHeight(label.getSize(), labelRotation) / 2.0f;
            default -> Label.getRotatedWidth(label.getSize(), labelRotation) / 2.0f;
          }
      );
      if (labelRotation != 0.0) {
        centerTransform.concatenate(AffineTransform.getRotateInstance(labelRotation));
      }
      if (i > 0 && label.getGraphicOffset() + Label.getRotatedWidth(label.getSize(), labelRotation) / 2.0f > this.prevMargin - 1) {
        continue;
      }
      this.prevMargin = label.getGraphicOffset() - Label.getRotatedWidth(label.getSize(), labelRotation) / 2.0f;
      this.graphics2d.setTransform(centerTransform);
      label.getLabelLayout().draw(this.graphics2d, -label.getWidth() / 2.0f, label.getHeight() / 2.0f);
    }
  }

  public final Graphics2D getGraphics2d() {
    return this.graphics2d;
  }

  public final ScaleBarRenderSettings getSettings() {
    return this.settings;
  }

  public final ScalebarAttributeValues getParams() {
    return this.params;
  }
}

