public class UnhealthyCountersHealthCheck extends HealthCheck {
  @Autowired private MetricRegistry metricRegistry;
  private final Set<String> unhealthyCounters;

  @Override protected HealthCheck.Result check() {
    final StringBuilder messageBuilder = new StringBuilder();
    boolean first = true;
    for (final String unhealthyCounter : this.unhealthyCounters) {
      if (this.metricRegistry.getNames().contains(unhealthyCounter)) {
        final Counter counter = this.metricRegistry.counter(unhealthyCounter);
        if (counter.getCount() != 0) {
          if (!first) {
            messageBuilder.append('\n');
          }
          messageBuilder.append(unhealthyCounter).append(" = ").append(counter.getCount());
          first = false;
        }
      }
    }
    return first ? Result.healthy("No unhealthy counter found.") : Result.unhealthy(messageBuilder.toString());
  }

  public void recordUnhealthyCounter(final String counterName) {
    this.unhealthyCounters.add(counterName);
  }

  public void recordUnhealthyProblem(final String className, final String description) {
    final String counterName = this.metricRegistry.name(className, description);
    this.metricRegistry.counter(counterName).inc();
    this.recordUnhealthyCounter(counterName);
  }
}

