public final class ProcessorGraphNode<IN, OUT> {
  private static final Logger LOGGER;
  private final Processor<IN, OUT> processor;
  private final Set<ProcessorGraphNode<?, ?>> dependencies;
  private final Set<ProcessorGraphNode> requirements;
  private final MetricRegistry metricRegistry;
  public ProcessorGraphNode(@Nonnull final Processor<IN, OUT> processor, @Nonnull final MetricRegistry metricRegistry) {
    this.processor = processor;
    this.dependencies = new HashSet<>();
    this.requirements = new HashSet<>();
    this.metricRegistry = metricRegistry;
  }
  public Processor<?, ?> getProcessor() {
    return this.processor;
  }
  public void addDependency(final ProcessorGraphNode node) {
    Assert.isTrue(node != this, "A processor can't depends on himself");
    this.dependencies.add(node);
    node.addRequirement(this);
  }
  private void addRequirement(final ProcessorGraphNode node) {
    this.requirements.add(node);
  }
  Set<ProcessorGraphNode> getRequirements() {
    return this.requirements;
  }
  Set<ProcessorGraphNode<?, ?>> getDependencies() {
    return this.dependencies;
  }
  public Optional<ProcessorNodeForkJoinTask<IN, OUT>> createTask(@Nonnull final ProcessorExecutionContext execContext) {
    return execContext.tryStart(this) ? Optional.of(new ProcessorNodeForkJoinTask<>(this, execContext)) : Optional.empty();
  }
  @Nonnull public BiMap<String, String> getOutputMapper() {
    return Objects.requireNonNullElseGet(this.processor.getOutputMapperBiMap(), HashBiMap::create);
  }
  @Nonnull public BiMap<String, String> getInputMapper() {
    return Objects.requireNonNullElseGet(this.processor.getInputMapperBiMap(), HashBiMap::create);
  }
  public void toString(final StringBuilder builder, final int indent, final String parent) {
    this.processor.toString(builder, indent, parent);
    this.dependencies.forEach(node -> node.toString(builder, indent + 1, this.processor.toString()));
  }
  @Override public String toString() {
    final StringBuilder builder = new StringBuilder();
    this.toString(builder, 0, "?");
    return builder.toString();
  }
  public String getName() {
    return this.processor.toString();
  }
  public Set<? extends Processor<?, ?>> getAllProcessors() {
    final IdentityHashMap<Processor<?, ?>, Void> processors = new IdentityHashMap<>();
    processors.put(this.processor, null);
    this.dependencies.forEach(node -> processors.putAll(node.getAllProcessors()));
    return processors.keySet();
  }
  public static final class ProcessorNodeForkJoinTask<In, Out> extends RecursiveTask<Values> {
    private final ProcessorExecutionContext execContext;
    private final ProcessorGraphNode<In, Out> node;
    private ProcessorNodeForkJoinTask(final ProcessorGraphNode<In, Out> node, final ProcessorExecutionContext execContext) {
      this.execContext = execContext;
      this.node = node;
    }
    @Override protected Values compute() {
      return this.execContext.getContext().mdcContext(() -> {
        final Values values = this.execContext.getValues();
        this.executeProcess(this.node.processor, values);
        return values;
      });
    }
    private void executeProcess(final Processor<In, Out> process, final Values values) {
      final String timerName = MetricRegistry.name(ProcessorGraphNode.class.getSimpleName(), "compute", process.getClass().getSimpleName());
      final Timer.Context timerContext = this.node.metricRegistry.timer(timerName).time();
      try {
        ProcessorUtils.populateInputParameter(process, values);
        final Out output = process.execute(inputParameter, this.execContext.getContext());
        LOGGER.debug("Succeeded in executing process: {}", process);
        ProcessorUtils.writeProcessorOutputToValues(output, process, values);
      } catch (final RuntimeException e) {
        throw this.handleException(e, e, process, timerName);
      } catch (final Exception e) {
        throw this.handleException(e, null, process, timerName);
      } finally {
        this.execContext.finished(this.node);
        timerContext.stop();
        LOGGER.info("Time taken to run processor: '{}' was {} ms", process.getClass(), TimeUnit.MILLISECONDS.convert(timerContext.stop(), TimeUnit.NANOSECONDS));
      }
    }
    private RuntimeException handleException(final Exception cause, final RuntimeException runtimeCause, final Processor<In, Out> process, final String timerName) {
      LOGGER.info("Error while executing process: {}", process, cause);
      this.execContext.getContext().stopIfCanceled();
      this.node.metricRegistry.counter(MetricRegistry.name(timerName, "error")).inc();
      return Objects.requireNonNullElseGet(runtimeCause, () -> new PrintException(String.format("Failed to execute process: %s", process), cause));
    }
  }
}

