  }
  public Optional<ProcessorNodeForkJoinTask<IN, OUT>> createTask(@Nonnull final ProcessorExecutionContext execContext) {
    return execContext.tryStart(this) ? Optional.of(new ProcessorNodeForkJoinTask<>(this, execContext)) : Optional.empty();
  }
  @Nonnull public BiMap<String, String> getOutputMapper() {
    return Objects.requireNonNullElseGet(this.processor.getOutputMapperBiMap(), HashBiMap::create);
  }
  @Nonnull public BiMap<String, String> getInputMapper() {
    return Objects.requireNonNullElseGet(this.processor.getInputMapperBiMap(), HashBiMap::create);
  }
  public void toString(final StringBuilder builder, final int indent, final String parent) {
    this.processor.toString(builder, indent, parent);
    this.dependencies.forEach(node -> node.toString(builder, indent + 1, this.processor.toString()));
  }
  @Override public String toString() {
