import com.google.common.collect.Lists;
import jakarta.inject.Inject;
import java.util.Comparator;
import java.util.Map;
import org.opentcs.strategies.basic.dispatching.AssignmentCandidate;
import org.opentcs.strategies.basic.dispatching.DefaultDispatcherConfiguration;
import org.opentcs.strategies.basic.dispatching.priorization.candidate.CandidateComparatorByOrderAge;
import org.opentcs.strategies.basic.dispatching.priorization.candidate.CandidateComparatorByOrderName;
import static org.opentcs.util.Assertions.checkArgument;

public class CompositeOrderCandidateComparator implements Comparator<AssignmentCandidate> {
  private final Comparator<AssignmentCandidate> compositeComparator;

  @Inject public CompositeOrderCandidateComparator(DefaultDispatcherConfiguration configuration, Map<String, Comparator<AssignmentCandidate>> availableComparators) {
    Comparator<AssignmentCandidate> configuredComparator = new CandidateComparatorByOrderAge()
        .thenComparing(new CandidateComparatorByOrderName());
    for (String priorityKey : Lists.reverse(configuration.orderCandidatePriorities())) {
      Comparator<AssignmentCandidate> configuredComparator = checkArgument(availableComparators.get(priorityKey) != null, "Unknown order candidate priority key: '%s'", priorityKey);
      compositeComparator = configuredComparator.thenComparing(compositeComparator);
    }
  }

  @Override public int compare(AssignmentCandidate o1, AssignmentCandidate o2) {
    return compositeComparator.compare(o1, o2);
  }
}

