package org.opentcs.strategies.basic.routing.jgrapht;

import jakarta.annotation.Nonnull;
import java.util.Set;
import java.util.stream.Collectors;
import org.jgrapht.Graph;
import org.jgrapht.graph.AbstractBaseGraph;
import org.opentcs.components.kernel.routing.Edge;
import org.opentcs.data.model.Path;
import org.opentcs.data.model.Point;
import org.opentcs.strategies.basic.routing.jgrapht.GraphProvider.GraphResult;
import static java.util.Objects.requireNonNull;

public class GraphMutator {
  public GraphMutator() {
  }

  public GraphResult deriveGraph(@Nonnull Set<Point> pointsToExclude, @Nonnull Set<Path> pathsToExclude, @Nonnull GraphResult baseGraph) {
    Graph<Vertex, Edge> derivedGraph = baseGraph.getGraph().clone();
    Set<String> pathsToExcludeByName = pathsToExclude.stream().map(Path::getName).collect(Collectors.toSet());
    baseGraph.getGraph().edgeSet().forEach(edge -> {
      if (pathsToExcludeByName.contains(edge.getPath().getName())) {
        derivedGraph.removeEdge(edge);
      } else {
        derivedGraph.setEdgeWeight(edge, baseGraph.getGraph().getEdgeWeight(edge));
      }
    });
    Set<String> pointsToExcludeByName = pointsToExclude.stream().map(Point::getName).collect(Collectors.toSet());
    baseGraph.getGraph().vertexSet().stream().filter(vertex -> pointsToExcludeByName.contains(vertex.getPoint().getName())).forEach(derivedGraph::removeVertex);
    return new GraphResult(baseGraph.getVehicle(), baseGraph.getPointBase(), baseGraph.getPathBase(), pointsToExclude, pathsToExclude, derivedGraph);
  }
}

