public class ResourceAvoidanceExtractor {
  private static final Logger LOG = LoggerFactory.getLogger(ResourceAvoidanceExtractor.class);
  private final TCSObjectService objectService;
  @Inject public ResourceAvoidanceExtractor(TCSObjectService objectService) {
    this.objectService = requireNonNull(objectService, "objectService");
  }
  @Nonnull public ResourcesToAvoid extractResourcesToAvoid(@Nullable TransportOrder order) {
    return order == null ? ResourcesToAvoid.EMPTY : extractResourcesToAvoid(order.getProperty(ObjectPropConstants.TRANSPORT_ORDER_RESOURCES_TO_AVOID));
  }
  @Nonnull public ResourcesToAvoid extractResourcesToAvoid(Set<TCSResourceReference<?>> resourcesToAvoid) {
    requireNonNull(resourcesToAvoid, "resourcesToAvoid");
    return resourcesToAvoid.isEmpty() ? ResourcesToAvoid.EMPTY : new ResourcesToAvoid(new HashSet<>(), new HashSet<>()).addAll(resourcesToAvoid);
  }
  public static class ResourcesToAvoid {
    public static final ResourcesToAvoid EMPTY = new ResourcesToAvoid(Set.of(), Set.of());
    private final Set<Point> points;
    private final Set<Path> paths;
    private ResourcesToAvoid(Set<Point> points, Set<Path> paths) {
      this.points = requireNonNull(points, "points");
      this.paths = requireNonNull(paths, "paths");
    }
    public Set<Point> getPoints() {
      return points;
    }
    public Set<Path> getPaths() {
      return paths;
    }
    public boolean isEmpty() {
      return points.isEmpty() && paths.isEmpty();
    }
    public Set<TCSResourceReference<?>> toResourceReferenceSet() {
      return Stream.concat(paths.stream().map(Path::getReference), points.stream().map(Point::getReference)).collect(Collectors.toSet());
    }
  }
}

