  public static final String CONFIGURATION_KEY;
  private static final Logger LOG;
  private final BoundingBoxProtrusionCheck protrusionCheck;
  private volatile PlantModel plantModel;
  @Inject public EdgeEvaluatorBoundingBox(BoundingBoxProtrusionCheck protrusionCheck) {
    this.protrusionCheck = requireNonNull(protrusionCheck, "protrusionCheck");
    this.plantModel = new PlantModel("");
  }
  @Override public boolean isParallelGraphComputationSupported() {
    return true;
  }
  @Override public void onRoutingContextUpdated(@Nonnull RoutingContext context) {
    plantModel = context.getPlantModel();
  }
  @Override public void onGraphComputationStart(@Nonnull Vehicle vehicle) {
  }
  @Override public void onGraphComputationEnd(@Nonnull Vehicle vehicle) {
  }
  @Override public double computeWeight(@Nonnull Edge edge, @Nonnull Vehicle vehicle) {
    return protrusionCheck.checkProtrusion(vehicle.getBoundingBox(),
                                           plantModel.getPoint(edge.getTargetVertex()).orElseThrow().getMaxVehicleBoundingBox())
            .protrudesAnywhere()
            ? Double.NaN
            : 0.0;
  }
}

