package org.opentcs.kernel.extensions.servicewebapi.common;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import java.io.IOException;

public class JsonBinder {
  private final ObjectMapper objectMapper;

  public JsonBinder() {
    objectMapper = new ObjectMapper();
    objectMapper.registerModule(new JavaTimeModule());
    objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
  }

  public <T> T fromJson(String jsonString, Class<T> clazz) throws IllegalArgumentException {
    try {
      return objectMapper.readValue(jsonString, clazz);
    } catch (IOException e) {
      throw new IllegalArgumentException("Could not parse JSON input", e);
    }
  }

  public String toJson(Object object) throws IllegalStateException {
    return objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(object);
  }

  public String toJson(Throwable t) throws IllegalStateException {
    return objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(objectMapper.createArrayNode().add(t.getMessage()));
  }
}

