import com.google.inject.Inject;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import org.opentcs.components.plantoverview.PropertySuggestions;
import static java.util.Objects.requireNonNull;

public class MergedPropertySuggestions implements PropertySuggestions {
  private final Set<String> keySuggestions;
  private final Set<String> valueSuggestions;
  private final Set<PropertySuggestions> propertySuggestions;
  @Inject public MergedPropertySuggestions(Set<PropertySuggestions> propertySuggestions) {
    this.keySuggestions = new TreeSet<>();
    this.valueSuggestions = new TreeSet<>();
    this.propertySuggestions = requireNonNull(propertySuggestions, "propertySuggestors");
    propertySuggestions.forEach(s -> {
      keySuggestions.addAll(s.getKeySuggestions());
      valueSuggestions.addAll(s.getValueSuggestions());
    });
  }
  @Override public Set<String> getKeySuggestions() {
    return keySuggestions;
  }
  @Override public Set<String> getValueSuggestions() {
    return valueSuggestions;
  }
  @Override public Set<String> getValueSuggestionsFor(String key) {
    return propertySuggestions.stream()
        .map(s -> s.getValueSuggestionsFor(key))
        .filter(s -> s != null)
        .flatMap(Set::stream)
        .collect(HashSet::new, HashSet::addAll, HashSet::addAll);
  }
}

