public class MyBatisUtils {
  private static final String MYSQL_ESCAPE_CHARACTER = "`";
  private static final Pattern SAFE_COLUMN_NAME_PATTERN;
  private static final String FIND_IN_SET_VALUE_PLACEHOLDER = "#{value}";
  private static final String FIND_IN_SET_COLUMN_PLACEHOLDER = "#{column}";
  public static <T> Page<T> buildPage(PageParam pageParam) {
    return buildPage(pageParam, null);
  }
  public static <T> Page<T> buildPage(PageParam pageParam, Collection<SortingField> sortingFields) {
    Page<T> page = new Page<>(pageParam.getPageNo(), pageParam.getPageSize());
    page.setOptimizeJoinOfCountSql(false);
    if (CollUtil.isNotEmpty(sortingFields)) {
      for (SortingField sortingField : sortingFields) {
        String columnName = buildSafeOrderColumn(sortingField.getField());
        if (columnName != null) {
          page.addOrder(new OrderItem().setAsc(isAscOrder(sortingField.getOrder())).setColumn(columnName));
        }
      }
    }
    return page;
  }
  @SuppressWarnings("PatternVariableCanBeUsed") public static <T> void addOrder(Wrapper<T> wrapper, Collection<SortingField> sortingFields) {
    if (CollUtil.isEmpty(sortingFields)) {
      return;
    }
    if (wrapper instanceof QueryWrapper) {
      for (SortingField sortingField : sortingFields) {
        wrapper.orderBy(true, isAscOrder(sortingField.getOrder()), buildSafeOrderColumn(sortingField.getField()));
      }
    } else if (wrapper instanceof LambdaQueryWrapper) {
      StringBuilder orderBy = new StringBuilder("ORDER BY ");
      for (SortingField sortingField : sortingFields) {
        if (isSafeColumnName(sortingField.getField())) {
          orderBy.append(sortingField.getField()).append(' ').append(getOrderDirection(sortingField.getOrder())).append(", ");
        }
      }
      if (orderBy.length() > "ORDER BY ".length()) {
        orderBy.delete(orderBy.length() - 2, orderBy.length());
        ((LambdaQueryWrapper<T>) wrapper).last(orderBy.toString());
      }
    } else {
      throw new IllegalArgumentException("Unsupported wrapper type: " + wrapper.getClass().getName());
    }
  }
  public static boolean isAscOrder(String order) {
    return SortingField.ORDER_ASC.equals(order);
  }
  public static String getOrderDirection(String order) {
    return isAscOrder(order) ? "ASC" : "DESC";
  }
  private static String buildSafeOrderColumn(String field) {
    return StrUtil.toUnderlineCase(field);
  }
  public static void addInterceptor(MybatisPlusInterceptor interceptor, InnerInterceptor inner, int index) {
    interceptor.setInterceptors(new ArrayList<>(interceptor.getInterceptors()).add(index, inner));
  }
  public static String getTableName(Table table) {
    return table.getName().startsWith(MYSQL_ESCAPE_CHARACTER) && table.getName().endsWith(MYSQL_ESCAPE_CHARACTER) ? table.getName().substring(1, table.getName().length() - 1) : table.getName();
  }
  public static Column buildColumn(String tableName, Alias tableAlias, String column) {
    return new Column(tableAlias != null ? tableAlias.getName() : tableName + StringPool.DOT + column);
  }
  public static String findInSet(String columnName) {
    return findInSet(columnName, 0);
  }
  public static String findInSetWithParamIndex(String columnName, int paramIndex) {
    return findInSet(columnName, paramIndex);
  }
  private static String findInSet(String columnName, int paramIndex) {
    return findInSet(JdbcUtils.getDbType(), columnName, paramIndex);
  }
  static String findInSet(DbType dbType, String columnName, int paramIndex) {
    return DbTypeEnum.getFindInSetTemplate(dbType).replace(FIND_IN_SET_COLUMN_PLACEHOLDER, columnName).replace(FIND_IN_SET_VALUE_PLACEHOLDER, "{" + paramIndex + "}");
  }
  private static boolean isSafeColumnName(String columnName) {
    return StrUtil.isNotEmpty(columnName) && SAFE_COLUMN_NAME_PATTERN.matcher(columnName).matches();
  }
  public static <T> String toUnderlineCase(Func1<T, ?> func) {
    return StrUtil.toUnderlineCase(LambdaUtil.getFieldName(func));
  }
}

